import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Bootstrap Test Runner (plugin-engine-test)","description":"","frontmatter":{"title":"Bootstrap Test Runner (`plugin-engine-test`)","type":"adr","date":"2026-10-15T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","status":"implemented","status_note":"Implemented — the runner lives in the engine-test repo (`hnl-engine-test`); `plugin-ext-test` is the capability adapter.","refs":["ADR-0085","ADR-0092"]},"headers":[],"relativePath":"handl/project/adrs/0089-bootstrap-test-runner.md","filePath":"vendored/handl/project/adrs/0089-bootstrap-test-runner.md"}'),a={name:`handl/project/adrs/0089-bootstrap-test-runner.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0089-bootstrap-test-runner-plugin-engine-test" tabindex="-1">ADR-0089: Bootstrap Test Runner (<code>plugin-engine-test</code>) <a class="header-anchor" href="#adr-0089-bootstrap-test-runner-plugin-engine-test" aria-label="Permalink to “ADR-0089: Bootstrap Test Runner (plugin-engine-test)”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>A new <code>plugin-engine-test</code> crate owns the runner</strong> — discovery, index, filter, planner, scheduler, engine, result store, summarizer, reporter — extracted from <code>plugin-lib-test</code>; it stays Rust (ADR-0085 §6).</li><li><strong><code>plugin-lib-test</code> becomes the framework library</strong> (<code>assert</code>/<code>property</code>/ <code>benchmark</code>/<code>fuzz</code>/<code>snapshot</code>), migrated to handl by ADR-0092 and then deleted.</li><li><strong>Stable pipeline contracts</strong>: Providers → Discovery → Index/Cache → Filter → Planner → Scheduler → Engine → ResultStore → Summarizer → Reporter.</li><li><strong>Core types are hard to change and versioned</strong>; internal contracts are versioned; failures are structured, never a bare <code>false</code>.</li><li><strong>Test declaration is a merged language fragment</strong>, not the <code>test_*</code> naming convention the v0.1 grammar forced.</li><li><strong>Providers are extensible from day one</strong>; discovery/index and filtering are predicate models.</li><li><strong>Planner and scheduler are separate; the scheduler is generic</strong>; the engine is pure by default and the capability model is generic.</li><li><strong>Determinism is a hard invariant</strong>; observability emits structured events from day one; engine genericity follows ADR-0081.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The original minimal runner discovered tests by the <code>test_*</code> naming workaround, ran them in source order, and deferred parallelism, properties, benchmarks, filtering, caching and providers to a future handl port. Bolting those on later means rewriting the runner; the pipeline boundaries are the decision.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Ship the toy runner, bolt features on later</strong> — the rewrite this ADR prevents.</li><li><strong>Keep <code>test_*</code> naming</strong> — a v0.1 grammar workaround; the test declaration is a language fragment.</li><li><strong>One monolithic stage</strong> — it welds discovery, scheduling and reporting together and makes any one of them unswappable.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>More structure up front (nine stage contracts) in exchange for additive features.</li><li>The runner stays Rust while the framework moves to handl; the runner consumes the framework through the module chain either way.</li><li>A temporary Rust handl may exist for <code>benchmark</code>/RNG until stdlib primitives land.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>engine-test/</code> (<code>hnl-engine-test</code>) — the runner.</li><li><code>crates/plugin-ext-test/</code> — the <code>test</code> capability adapter.</li><li><code>tests/</code> in the engine and host — pipeline and determinism tests.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Stage contracts, providers, cache domains and the CLI/API surface: +<a href="./../design/0089-bootstrap-test-runner.html"><code>design/0089-bootstrap-test-runner.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};